  '여행을 만들 때 미리 채워 드려요. 마이페이지 › 여행 취향에서 언제든 바꿀 수 있어요.': { ja: '旅行を作成する際に自動で入力されます。マイページ›旅行の好みでいつでも変更できます。', zhHans: '在制定旅行时会自动为您填写。您可以随时在个人主页›旅行偏好中更改。', zhHant: '在制定旅行時會自動為您填寫。您可以隨時在個人主頁›旅行偏好中更改。' },
  '여행 취향을 5개만 여쭤볼게요': { ja: '旅行の好みについて5つだけお聞きします', zhHans: '只问您5个关于旅行偏好的问题', zhHant: '只問您5個關於旅行偏好的問題' },
