  '이용 조건': { ja: '利用条件', zhHans: '使用条件', zhHant: '使用條件' },
  '알레르기·식단 정보가 없는 장소는 안전하다고 추정하지 않아요.': { ja: 'アレルギー・食事情報がない場所は安全だと推定しません。', zhHans: '没有过敏或饮食信息的地方,我们不会假定它是安全的。', zhHant: '沒有過敏或飲食資訊的地方,我們不會假定它是安全的。' },
  '미확인 필수 조건이 있어요. 제약 조건을 확인해 주세요 →': { ja: '未確認の必須条件があります。制約条件をご確認ください →', zhHans: '有未确认的必要条件,请查看限制条件 →', zhHant: '有未確認的必要條件,請查看限制條件 →' },
  '도보 위주 이동과 500m 이하 보행 제한이 함께 선택됐어요. 생성 전에 이동수단을 확인해 주세요.': { ja: '徒歩中心の移動と500m以下の歩行制限が同時に選択されています。作成前に移動手段をご確認ください。', zhHans: '您同时选择了以步行为主的出行方式和500米以下的步行限制。请在生成前确认交通方式。', zhHant: '您同時選擇了以步行為主的出行方式和500公尺以下的步行限制。請在生成前確認交通方式。' },
  '장소 운영시간·접근성·혼잡도는 최신 정보가 아닐 수 있어요. 최종 방문 전 공식 정보를 확인해 주세요.': { ja: '場所の営業時間・アクセス性・混雑度は最新情報でない場合があります。訪問前に公式情報をご確認ください。', zhHans: '场所的营业时间、无障碍信息和拥挤程度可能不是最新的。请在实际到访前查看官方信息。', zhHant: '場所的營業時間、無障礙資訊和擁擠程度可能不是最新的。請在實際造訪前查看官方資訊。' },
  '이후 진행 단계': { ja: '今後の進行段階', zhHans: '后续流程', zhHant: '後續流程' },
  '조건 검토 → 추천 장소 구성 → 이동 동선 확인 → 일정 완성': { ja: '条件確認 → おすすめ場所の構成 → 移動ルートの確認 → 日程完成', zhHans: '确认条件 → 组建推荐地点 → 确认交通路线 → 完成行程', zhHant: '確認條件 → 組建推薦地點 → 確認交通路線 → 完成行程' },
  '알레르기·식단 정보 사용에 동의가 필요해요': { ja: 'アレルギー・食事情報の利用に同意が必要です', zhHans: '需要您同意使用过敏/饮食信息', zhHant: '需要您同意使用過敏/飲食資訊' },
  '입력하신 알레르기·필수 식단 조건으로 안전한 장소만 추천하려면 건강 정보 사용에 동의해 주세요. 언제든 마이페이지에서 철회할 수 있어요.': { ja: '入力されたアレルギー・必須食事条件に基づいて安全な場所だけをおすすめするには、健康情報利用への同意が必要です。マイページでいつでも同意を撤回できます。', zhHans: '为了仅推荐符合您输入的过敏/必需饮食条件的安全场所,请同意使用健康信息。您可以随时在个人主页撤回同意。', zhHant: '為了僅推薦符合您輸入的過敏/必需飲食條件的安全場所,請同意使用健康資訊。您可以隨時在個人主頁撤回同意。' },
  '처리 중…': { ja: '処理中…', zhHans: '处理中…', zhHant: '處理中…' },
  '동의하고 계속하기': { ja: '同意して続ける', zhHans: '同意并继续', zhHant: '同意並繼續' },
  '입력한 조건은 그대로 보관돼요. 서버가 준비되면 아래 버튼으로 다시 요청할 수 있어요.': { ja: '入力した条件はそのまま保存されます。サーバーの準備ができたら下のボタンで再度リクエストできます。', zhHans: '您输入的条件会保留。服务器就绪后,可以点击下方按钮重新请求。', zhHant: '您輸入的條件會保留。伺服器就緒後,可以點擊下方按鈕重新請求。' },
  '조건 다시 확인': { ja: '条件を再確認', zhHans: '重新确认条件', zhHant: '重新確認條件' },
  '서버 연결을 확인하고 있어요. 잠시 후 다시 시도해 주세요.': { ja: 'サーバー接続を確認しています。しばらくしてから再度お試しください。', zhHans: '正在确认服务器连接,请稍后再试。', zhHant: '正在確認伺服器連線,請稍後再試。' },
  '미확인 제약 조건을 먼저 확인해 주세요.': { ja: '未確認の制約条件を先にご確認ください。', zhHans: '请先确认未回答的限制条件。', zhHant: '請先確認未回答的限制條件。' },
  '일정 생성을 요청합니다.': { ja: '日程作成をリクエストします。', zhHans: '请求生成行程。', zhHant: '請求生成行程。' },
  '로그인 후 입력한 조건으로 일정 생성을 계속합니다.': { ja: 'ログイン後、入力した条件で日程作成を続けます。', zhHans: '登录后将继续使用这些条件生成行程。', zhHant: '登入後將繼續使用這些條件生成行程。' },
  '로그인 상태 확인 중…': { ja: 'ログイン状態を確認中…', zhHans: '正在检查登录状态…', zhHant: '正在檢查登入狀態…' },
