  '아니요': { ja: 'いいえ', zhHans: '否', zhHant: '否' },
  '제약 조건': { ja: '制約条件', zhHans: '旅行限制条件', zhHant: '旅行限制條件' },
  'AI가 아래 조건을 임의로 완화하지 않습니다.': { ja: 'AIは以下の条件を勝手に緩和しません。', zhHans: 'AI 不会擅自放宽以下条件。', zhHant: 'AI 不會擅自放寬以下條件。' },
  '1 / 3 · 안전 조건': { ja: '1 / 3 ・安全条件', zhHans: '1 / 3 · 安全条件', zhHant: '1 / 3 · 安全條件' },
  '두 항목만 확인하면 돼요 · 약 20초': { ja: '2項目だけ確認すればOK ・約20秒', zhHans: '只需确认两项 · 约20秒', zhHant: '只需確認兩項 · 約20秒' },
  '해당 여부를 반드시 알려주세요. 선택한 재료는 추천에서 제외해요.': { ja: '該当するかどうかを必ずお知らせください。選択した食材はおすすめから除外されます。', zhHans: '请务必告知我们是否符合。所选食材会从推荐中排除。', zhHant: '請務必告知我們是否符合。所選食材會從推薦中排除。' },
  '안전한 저장을 위해 현재 지원하는 항목만 선택할 수 있어요.': { ja: '安全な保存のため、現在サポートしている項目のみ選択できます。', zhHans: '为了安全存储,目前只能选择支持的项目。', zhHant: '為了安全存儲,目前只能選擇支援的項目。' },
  '알레르기 유무를 선택해 주세요.': { ja: 'アレルギーの有無を選択してください。', zhHans: '请选择是否有过敏。', zhHant: '請選擇是否有過敏。' },
  '알레르기 항목을 하나 이상 선택해 주세요.': { ja: 'アレルギー項目を1つ以上選択してください。', zhHans: '请至少选择一项过敏原。', zhHant: '請至少選擇一項過敏原。' },
  '적용할 식단이 없다면 ‘해당 없음’을 선택해 주세요.': { ja: '該当する食事制限がない場合は「該当なし」を選択してください。', zhHans: '如果没有饮食限制,请选择"无"。', zhHant: '如果沒有飲食限制,請選擇「無」。' },
