  '아래는 정해진 두 구간을 실제로 재어 본 값이에요. 이 여행의 경로를 잰 것은 아니에요.': { ja: '下記は決められた2区間を実際に測定した値です。この旅行の経路を測ったものではありません。', zhHans: '以下是对两条固定路段实际测量的数值,并非本次旅行路线的测量结果。', zhHant: '以下是對兩條固定路段實際測量的數值,並非本次旅行路線的測量結果。' },
  '일부 구간은 데이터가 없어 판정하지 않았습니다. 모르는 것을 아는 척하지 않습니다.': { ja: '一部の区間はデータがなく判定していません。知らないことを知っているふりはしません。', zhHans: '部分路段因数据不足未予评定。我们不会不懂装懂。', zhHant: '部分路段因數據不足未予評定。我們不會不懂裝懂。' },
