  '붙이지 않으면 여행 카드에는 날짜 ': { ja: '付けない場合、旅行カードには日付', zhHans: '若不命名,旅行卡片将显示日期', zhHant: '若不命名,旅行卡片將顯示日期' },
  '가 보여요.': { ja: 'が表示されます。', zhHans: '。', zhHant: '。' },
  '건너뛰기 · 날짜로 둘게요': { ja: 'スキップ ・日付のままにします', zhHans: '跳过 · 保留日期', zhHant: '跳過 · 保留日期' },
