  '비워 두면 이름 없이 날짜가 보여요': { ja: '空欄のままにすると名前なしで日付が表示されます', zhHans: '留空则不显示名称,只显示日期', zhHant: '留空則不顯示名稱,只顯示日期' },
  '앞뒤 공백은 저장할 때 지워져요': { ja: '前後の空白は保存時に削除されます', zhHans: '保存时会去除首尾空格', zhHant: '保存時會去除首尾空格' },
  '여행 카드에 이렇게 보여요': { ja: '旅行カードにはこう表示されます', zhHans: '旅行卡片将如下所示', zhHant: '旅行卡片將如下所示' },
  '이름이 없어서 날짜가 보여요': { ja: '名前がないため日付が表示されます', zhHans: '因未命名,显示日期', zhHant: '因未命名,顯示日期' },
  '이 이름으로 저장': { ja: 'この名前で保存', zhHans: '保存此名称', zhHant: '保存此名稱' },
  '이름 없이 · 날짜로 둘게요': { ja: '名前なしで ・日付のままにします', zhHans: '不命名 · 保留日期', zhHant: '不命名 · 保留日期' },
