  '초대 링크는 여행 소유자와 권한을 확인한 뒤 만들 수 있어요.': { ja: '招待リンクは旅行の所有者と権限を確認した後に作成できます。', zhHans: '邀请链接将在确认旅行所有者和权限后生成。', zhHant: '邀請連結將在確認旅行擁有者和權限後生成。' },
