  '가볼래 계정이 없어도 볼 수 있어요. 날짜별 일정만 보이고 출발지·연락처·예산·인원은 공유되지 않아요. 30일 뒤 만료돼요.': { ja: 'GABOLLEアカウントがなくても見られます。日付ごとの日程のみ表示され、出発地・連絡先・予算・人数は共有されません。30日後に失効します。', zhHans: '无需 GABOLLE 账户即可查看。仅显示每日行程,不会分享出发地、联系方式、预算和人数。30天后失效。', zhHant: '無需 GABOLLE 帳戶即可查看。僅顯示每日行程,不會分享出發地、聯絡方式、預算和人數。30天後失效。' },
