  '요청한 화면이 없거나 주소가 변경됐어요.\n안전하게 홈에서 여행을 다시 이어가세요.': { ja: 'リクエストされた画面がないか、アドレスが変更されました。\n安全にホームから旅行を続けてください。', zhHans: '您要查找的页面不存在或已变更。\n请返回首页安全地继续您的旅行。', zhHant: '您要查找的頁面不存在或已變更。\n請返回首頁安全地繼續您的旅行。' },
  '경로 재안내': { ja: 'ルート再案内', zhHans: '重新导航', zhHant: '重新導航' },
  '홈으로 돌아갈까요?': { ja: 'ホームに戻りますか?', zhHans: '要返回首页吗?', zhHant: '要返回首頁嗎?' },
  '입력한 주소는 표시하거나 저장하지 않아요. 이전에 둘러보던 여행 정보도 그대로 유지돼요.': { ja: '入力したアドレスは表示・保存しません。以前閲覧していた旅行情報もそのまま維持されます。', zhHans: '我们不会显示或保存您输入的网址。您之前浏览的旅行信息也会保持原样。', zhHant: '我們不會顯示或保存您輸入的網址。您之前瀏覽的旅行資訊也會保持原樣。' },
  '웹 홈으로 돌아가기': { ja: 'ウェブホームに戻る', zhHans: '返回网页首页', zhHant: '返回網頁首頁' },
