  '현장 문장은 크게 보거나 음성으로 듣고, 메뉴판 번역 도구도 바로 열 수 있어요.': { ja: '現地で使う文章を大きく表示したり音声で聞いたりでき、メニュー翻訳ツールもすぐに開けます。', zhHans: '可以放大查看或语音收听现场用语,也能立即打开菜单翻译工具。', zhHant: '可以放大查看或語音收聽現場用語,也能立即打開菜單翻譯工具。' },
  '안녕하세요! 부산 일정과 여행 중 필요한 말을 앱 기능으로 바로 도와드릴게요.': { ja: 'こんにちは!釜山の日程や旅行中に必要な言葉を、アプリ機能ですぐにお手伝いします。', zhHans: '您好!我可以通过应用功能立即帮您处理釜山行程和旅行中需要的用语。', zhHant: '您好!我可以透過應用程式功能立即幫您處理釜山行程和旅行中需要的用語。' },
