  '아직 담은 장소가 없어요.': { ja: 'まだ追加した場所がありません。', zhHans: '此列表尚无地点。', zhHant: '此清單尚無地點。' },
  '빼기': { ja: '削除', zhHans: '移除', zhHant: '移除' },
  '나만의 부산 컬렉션': { ja: '私だけの釜山コレクション', zhHans: '我的釜山收藏', zhHant: '我的釜山收藏' },
  '내가 직접 가보고, 좋아한 장소들을 모아보세요.': { ja: '自分で訪れて気に入った場所を集めてみましょう。', zhHans: '收集您亲自造访并喜欢的地点。', zhHant: '收集您親自造訪並喜歡的地點。' },
  '계정에 저장된 것을 불러오고 있어요.': { ja: 'アカウントに保存された内容を読み込んでいます。', zhHans: '正在加载账户中保存的内容…', zhHant: '正在載入帳戶中保存的內容…' },
  '내 계정에 저장돼요. 다른 기기에서도 보여요.': { ja: 'アカウントに保存されます。他の端末でも表示されます。', zhHans: '已保存到您的账户,您在其他设备上也能看到。', zhHant: '已保存到您的帳戶,您在其他裝置上也能看到。' },
  '이 기기에만 저장돼요. 로그인하면 계정에 저장돼요.': { ja: 'この端末にのみ保存されます。ログインするとアカウントに保存されます。', zhHans: '仅保存在此设备上。登录后即可保存到账户。', zhHant: '僅保存在此裝置上。登入後即可保存到帳戶。' },
  '내 리스트': { ja: 'マイリスト', zhHans: '我的列表', zhHant: '我的清單' },
