  '리스트 이름': { ja: 'リスト名', zhHans: '列表名称', zhHant: '清單名稱' },
  '예: 다시 가고 싶은 카페': { ja: '例:また行きたいカフェ', zhHans: '例如:想再去的咖啡厅', zhHant: '例如:想再去的咖啡廳' },
  '만들기': { ja: '作成', zhHans: '创建', zhHant: '建立' },
  '아직 리스트가 없어요.': { ja: 'まだリストがありません。', zhHans: '尚无列表。', zhHant: '尚無清單。' },
  '원하는 이름으로 첫 리스트를 만들어 보세요.': { ja: 'お好きな名前で最初のリストを作成してみましょう。', zhHans: '用您喜欢的名称创建第一个列表吧。', zhHant: '用您喜歡的名稱建立第一個清單吧。' },
  '지금은 계정과 못 맞췄어요. 이 기기에 있는 것을 보여드려요.': { ja: '現在アカウントと同期できていません。この端末にあるものを表示します。', zhHans: '目前无法与账户同步,显示的是此设备上的内容。', zhHant: '目前無法與帳戶同步,顯示的是此裝置上的內容。' },
  '사진 없음': { ja: '写真なし', zhHans: '暂无照片', zhHant: '尚無照片' },
  '이 기기에만 있어요 — 이름을 줄이면 계정에 올라가요': { ja: 'この端末にのみあります — 名前を短くするとアカウントに反映されます', zhHans: '仅存在于此设备 — 缩短名称即可同步到账户', zhHant: '僅存在於此裝置 — 縮短名稱即可同步到帳戶' },
  '최근 추가한 장소': { ja: '最近追加した場所', zhHans: '最近添加的地点', zhHant: '最近新增的地點' },
  '부산 로컬 탐색': { ja: '釜山ローカル探索', zhHans: '像本地人一样探索釜山', zhHant: '像在地人一樣探索釜山' },
  '관심 갈래를 고르고 내 근처 또는 부산 전체에서 찾아보세요.': { ja: '興味のあるジャンルを選んで、近くまたは釜山全体から探してみてください。', zhHans: '选择感兴趣的类别,在附近或整个釜山范围内搜索。', zhHant: '選擇感興趣的類別,在附近或整個釜山範圍內搜尋。' },
  '갈래를 불러오고 있어요': { ja: 'ジャンルを読み込んでいます', zhHans: '正在加载类别', zhHant: '正在載入類別' },
  '로컬 탐색 API를 기다리고 있어요': { ja: 'ローカル探索APIを待っています', zhHans: '正在等待本地探索接口', zhHant: '正在等待在地探索介面' },
  '갈래를 불러오지 못했어요': { ja: 'ジャンルを読み込めませんでした', zhHans: '无法加载类别', zhHant: '無法載入類別' },
  '지금은 둘러볼 수 있는 갈래가 없어요. 자료가 들어오면 다시 열어 드릴게요.': { ja: '現在見て回れるジャンルがありません。データが入り次第再度お知らせします。', zhHans: '目前没有可浏览的类别,数据更新后会再次开放。', zhHant: '目前沒有可瀏覽的類別,數據更新後會再次開放。' },
  '내 근처': { ja: '近く', zhHans: '附近', zhHant: '附近' },
  '부산 전체': { ja: '釜山全体', zhHans: '全部釜山', zhHant: '全部釜山' },
  '부산 전체는 거리 제한 없이 찾아요.': { ja: '釜山全体は距離制限なしで検索します。', zhHans: '"全部釜山"不限距离进行搜索。', zhHant: '「全部釜山」不限距離進行搜尋。' },
  '내 근처는 반경 안에서 찾아요. 결과의 검색 범위를 확인하거나 부산 전체로 바꿔 보세요.': { ja: '近くは半径内で検索します。結果の検索範囲を確認するか、釜山全体に切り替えてください。', zhHans: '"附近"在一定半径内搜索。请查看结果显示的范围,或切换为"全部釜山"。', zhHant: '「附近」在一定半徑內搜尋。請查看結果顯示的範圍,或切換為「全部釜山」。' },
  '장소를 불러오지 못했어요.': { ja: '場所を読み込めませんでした。', zhHans: '无法加载地点。', zhHant: '無法載入地點。' },
  '부산 전체에서도 이 갈래의 장소를 찾지 못했어요.': { ja: '釜山全体でもこのジャンルの場所は見つかりませんでした。', zhHans: '在整个釜山范围内也未找到此类别的地点。', zhHant: '在整個釜山範圍內也未找到此類別的地點。' },
  '내 위치를 몰라 부산 중심에서 찾았어요. 거리도 그 기준이에요.': { ja: '位置情報が不明なため釜山の中心から検索しました。距離もその地点を基準にしています。', zhHans: '由于无法获取您的位置,已从釜山市中心开始搜索,距离也以此为基准。', zhHant: '由於無法取得您的位置,已從釜山市中心開始搜尋,距離也以此為基準。' },
  '내 위치로 다시 찾기': { ja: '現在地で再検索', zhHans: '从我的位置重新搜索', zhHant: '從我的位置重新搜尋' },
  '설정에서 위치 허용하기': { ja: '設定で位置情報を許可', zhHans: '在设置中允许位置权限', zhHant: '在設定中允許位置權限' },
  '이제 이 사용자에게 내 글이 보이지 않아요.': { ja: 'これでこのユーザーには自分の投稿が表示されなくなります。', zhHans: '该用户现在将无法看到您的帖子。', zhHant: '該使用者現在將無法看到您的貼文。' },
