  '삭제됐거나, 볼 수 없는 기록이에요.': { ja: '削除されたか、閲覧できない記録です。', zhHans: '该记录已被删除,或您无权查看。', zhHant: '該記錄已被刪除,或您無權查看。' },
  '기록을 불러오지 못했어요': { ja: '記録を読み込めませんでした', zhHans: '无法加载该记录', zhHant: '無法載入該記錄' },
  '가볼래 기록 함께 쓰기': { ja: 'GABOLLE記録共同執筆', zhHans: 'GABOLLE 记录共同撰写', zhHant: 'GABOLLE 記錄共同撰寫' },
  '함께 쓰는 기록': { ja: '共同執筆の記録', zhHans: '共同撰写的记录', zhHant: '共同撰寫的記錄' },
  '이 기록을 함께 쓰는 사람들이에요.': { ja: 'この記録を一緒に書いている人たちです。', zhHans: '共同撰写此记录的所有人。', zhHant: '共同撰寫此記錄的所有人。' },
  '이 기록을 볼 수 있는 사람만 볼 수 있어요': { ja: 'この記録を見られる人だけが閲覧できます', zhHans: '仅可查看此记录的人可以查看', zhHant: '僅可查看此記錄的人可以查看' },
  '만든 사람': { ja: '作成者', zhHans: '作者', zhHant: '作者' },
