  '여행 동행자 추가': { ja: '旅行同行者を追加', zhHans: '添加旅行同伴', zhHant: '新增旅行同伴' },
  '여행 동행자 고르기': { ja: '旅行同行者を選ぶ', zhHans: '选择旅行同伴', zhHant: '選擇旅行同伴' },
  '추가할 수 있는 동행자가 없어요 — 이미 모두 참여 중이에요.': { ja: '追加できる同行者がいません — 全員すでに参加中です。', zhHans: '没有可添加的同伴了——大家都已经是参与者。', zhHant: '沒有可新增的同伴了——大家都已經是參與者。' },
  '오늘 부산에서 있었던 일을 남겨보세요': { ja: '今日釜山であったことを記録してみましょう', zhHans: '记录一下您今天在釜山的经历吧', zhHant: '記錄一下您今天在釜山的經歷吧' },
  '← 다시 쓰기': { ja: '← 編集に戻る', zhHans: '← 返回编辑', zhHant: '← 返回編輯' },
