  '선택한 기간과 부산 지역을 기준으로 조회합니다.': { ja: '選択した期間と釜山地域を基準に検索します。', zhHans: '将根据您所选的期间和釜山地区进行查询。', zhHant: '將根據您所選的期間和釜山地區進行查詢。' },
  '불러오지 못했습니다': { ja: '読み込めませんでした', zhHans: '无法加载', zhHant: '無法載入' },
