  '바꾸는 방향 뒤집기': { ja: '変換方向を切り替え', zhHans: '切换换算方向', zhHant: '切換換算方向' },
  '방향 바꾸기 ⇅': { ja: '方向切替 ⇅', zhHans: '切换方向 ⇅', zhHant: '切換方向 ⇅' },
