  '사진에 적힌 글자를 읽어 드려요. 번역이 아니라 읽기예요.': { ja: '写真に書かれた文字を読み上げます。翻訳ではなく読み取りです。', zhHans: '我们会读取照片上的文字——是读取,不是翻译。', zhHant: '我們會讀取照片上的文字——是讀取,不是翻譯。' },
  '사진은 글자를 읽는 동안만 쓰이고 저장하지 않아요': { ja: '写真は文字を読み取る間だけ使用され、保存されません', zhHans: '照片仅在读取文字期间使用,不会被保存', zhHant: '照片僅在讀取文字期間使用,不會被保存' },
  '글자를 읽어 주는 바깥 서비스로 사진이 한 번 전달돼요. 촬영 위치 정보는 보내기 전에 지워요. 사람 얼굴이나 영수증이 함께 찍히지 않게 해주세요.': { ja: '文字を読み取る外部サービスに写真が一度送信されます。撮影位置情報は送信前に削除されます。人の顔や領収書が一緒に写らないようにしてください。', zhHans: '照片会被发送一次给外部文字识别服务。发送前会移除拍摄位置信息。请避免拍到人脸或收据。', zhHant: '照片會被傳送一次給外部文字辨識服務。傳送前會移除拍攝位置資訊。請避免拍到人臉或收據。' },
  '사진 찍기': { ja: '写真を撮る', zhHans: '拍照', zhHant: '拍照' },
  '앨범에서 고르기': { ja: 'アルバムから選ぶ', zhHans: '从相册选择', zhHant: '從相簿選擇' },
  '찍은 메뉴판 사진': { ja: '撮影したメニュー写真', zhHans: '您拍摄的菜单照片', zhHant: '您拍攝的菜單照片' },
  '글자를 읽고 있어요': { ja: '文字を読み取っています', zhHans: '正在读取文字', zhHant: '正在讀取文字' },
  '사진이 클수록 조금 더 걸려요.': { ja: '写真が大きいほど少し時間がかかります。', zhHans: '照片越大,处理时间稍长。', zhHant: '照片越大,處理時間稍長。' },
