  '다른 사진으로 다시': { ja: '別の写真で再試行', zhHans: '换一张照片重试', zhHant: '換一張照片重試' },
  '사진에서 읽은 글자 · 추정': { ja: '写真から読み取った文字 ・推定', zhHans: '从照片读取的文字 · 估计', zhHant: '從照片讀取的文字 · 估計' },
  '사진은 예시예요 — 이 식당의 음식이 아니에요': { ja: '写真は例です — この店の料理ではありません', zhHans: '图片仅为示例——并非该餐厅的实际菜品', zhHant: '圖片僅為範例——並非該餐廳的實際菜品' },
  '듣기': { ja: '聞く', zhHans: '收听', zhHant: '收聽' },
  '다른 메뉴판 찍기': { ja: '別のメニューを撮影', zhHans: '拍摄其他菜单', zhHant: '拍攝其他菜單' },
  '번역은 로그인한 뒤에 쓸 수 있어요. 지금은 입력한 그대로 읽어드릴게요.': { ja: '翻訳はログイン後に利用できます。今は入力した内容をそのまま読み上げます。', zhHans: '翻译功能需要登录后才能使用。目前我们会按您输入的原文朗读。', zhHant: '翻譯功能需要登入後才能使用。目前我們會按您輸入的原文朗讀。' },
  '번역 기능이 아직 서버에 없어요. 입력한 그대로 읽어드릴게요.': { ja: '翻訳機能はまだサーバーにありません。入力した内容をそのまま読み上げます。', zhHans: '服务器上暂无翻译功能。我们会按您输入的原文朗读。', zhHant: '伺服器上暫無翻譯功能。我們會按您輸入的原文朗讀。' },
  '번역이 잠시 안 돼요. 잠시 후 다시 시도해 주세요. 지금은 입력한 그대로 읽어드릴게요.': { ja: '翻訳が一時的にできません。しばらくしてから再度お試しください。今は入力した内容をそのまま読み上げます。', zhHans: '翻译暂时无法使用,请稍后再试。目前我们会按您输入的原文朗读。', zhHant: '翻譯暫時無法使用,請稍後再試。目前我們會按您輸入的原文朗讀。' },
  '번역하지 못했어요. 입력한 그대로 읽어드릴게요.': { ja: '翻訳できませんでした。入力した内容をそのまま読み上げます。', zhHans: '无法翻译。我们会按您输入的原文朗读。', zhHant: '無法翻譯。我們會按您輸入的原文朗讀。' },
  '여행 중': { ja: '旅行中', zhHans: '旅行中', zhHant: '旅行中' },
