  '로그인하면 장소를 찾을 수 있어요.': { ja: 'ログインすると場所を検索できます。', zhHans: '登录后即可搜索地点。', zhHant: '登入後即可搜尋地點。' },
  '지금은 장소를 못 찾았어요. 잠시 후 다시 시도해 주세요.': { ja: '現在場所を検索できませんでした。しばらくしてから再度お試しください。', zhHans: '目前无法搜索地点,请稍后再试。', zhHant: '目前無法搜尋地點,請稍後再試。' },
  '메뉴판 읽기': { ja: 'メニューを読む', zhHans: '读取菜单', zhHant: '讀取菜單' },
  '찍으면 적힌 글자를 읽어 드려요. 알레르기 낱말도 같이 찾아요': { ja: '撮影すると書かれた文字を読み上げます。アレルギー関連の単語も一緒に探します', zhHans: '拍照后我们会读取文字,同时查找过敏相关词汇', zhHant: '拍照後我們會讀取文字,同時查找過敏相關詞彙' },
  '장소별 한국어': { ja: '場所別韓国語', zhHans: '按场景分类的韩语短句', zhHant: '按場景分類的韓語短句' },
  '택시·식당에서 바로 보여주는 문장': { ja: 'タクシー・飲食店ですぐ見せる文', zhHans: '在出租车和餐厅可立即展示的句子', zhHant: '在計程車和餐廳可立即展示的句子' },
  '가격표를 보고 바로 내 돈으로 바꿔 보세요': { ja: '値札を見てすぐに自国の通貨に換算してみましょう', zhHans: '看到价格标签,立即换算成您的货币', zhHant: '看到價格標籤,立即換算成您的貨幣' },
  '몇 분 뒤에 오는지 보고 기다릴지 정하세요': { ja: 'あと何分で来るか見て、待つかどうか決めましょう', zhHans: '看看还要等几分钟,再决定是否等待', zhHant: '看看還要等幾分鐘,再決定是否等待' },
