  '여행을 고르면 출발일 예보와 준비물을 보여드려요': { ja: '旅行を選ぶと出発日の予報と持ち物を表示します', zhHans: '选择旅行即可查看出发日天气预报和行李建议', zhHant: '選擇旅行即可查看出發日天氣預報和行李建議' },
  '여행 중 필요한 기능을 한곳에서 바로 사용해요': { ja: '旅行中に必要な機能を一か所ですぐに使えます', zhHans: '旅行中所需的功能都集中在一处,随时可用', zhHant: '旅行中所需的功能都集中在一處,隨時可用' },
  '[가볼래] 앱 문의': { ja: '[GABOLLE] アプリお問い合わせ', zhHans: '[GABOLLE] 应用咨询', zhHant: '[GABOLLE] 應用程式諮詢' },
  '문의 내용:\n\n문제가 발생한 화면:\n\n재현 순서:\n': { ja: 'お問い合わせ内容:\n\n問題が発生した画面:\n\n再現手順:\n', zhHans: '咨询内容:\n\n发生问题的页面:\n\n重现步骤:\n', zhHant: '諮詢內容:\n\n發生問題的頁面:\n\n重現步驟:\n' },
  '처음이어도 괜찮아요': { ja: '初めてでも大丈夫です', zhHans: '新手也没问题', zhHant: '新手也沒問題' },
  '가볼래가 무엇을 하는지 다시 보고, 막힌 문제를 해결해 보세요.': { ja: 'GABOLLEが何をするのかもう一度確認し、詰まった問題を解決してみましょう。', zhHans: '重新查看 GABOLLE 的功能介绍,并解决您遇到的问题。', zhHant: '重新查看 GABOLLE 的功能介紹,並解決您遇到的問題。' },
  '가볼래 한눈에 보기': { ja: 'GABOLLEをひと目で見る', zhHans: '一览 GABOLLE', zhHant: '一覽 GABOLLE' },
  'AI 일정·부산 장소·현장 말하기를 1분 안에 둘러봐요.': { ja: 'AI日程・釜山の場所・現地会話を1分以内で見て回りましょう。', zhHans: '1分钟内快速了解 AI 行程规划、釜山地点和现场对话功能。', zhHant: '1分鐘內快速了解 AI 行程規劃、釜山地點和現場對話功能。' },
  '앱 소개 다시 보기': { ja: 'アプリ紹介をもう一度見る', zhHans: '重新查看应用介绍', zhHant: '重新查看應用程式介紹' },
  '자주 묻는 질문': { ja: 'よくある質問', zhHans: '常见问题', zhHant: '常見問題' },
  '답을 찾지 못했나요?': { ja: '答えが見つかりませんでしたか?', zhHans: '没有找到答案吗?', zhHant: '沒有找到答案嗎?' },
  '문의 메일에는 문제가 난 화면과 재현 순서를 함께 적어 주세요.': { ja: 'お問い合わせメールには問題が発生した画面と再現手順を一緒に記載してください。', zhHans: '请在咨询邮件中注明发生问题的页面和重现步骤。', zhHant: '請在諮詢郵件中註明發生問題的頁面和重現步驟。' },
  '이메일로 문의하기': { ja: 'メールで問い合わせる', zhHans: '通过电子邮件咨询', zhHant: '透過電子郵件諮詢' },
  '문의 수신 주소를 준비하고 있어요. 그 전에는 팀에 화면 이름과 증상을 전달해 주세요.': { ja: 'お問い合わせ受信アドレスを準備中です。それまではチームに画面名と症状をお伝えください。', zhHans: '咨询收件地址正在准备中。在此之前,请将页面名称和问题现象告知团队。', zhHant: '諮詢收件地址正在準備中。在此之前,請將頁面名稱和問題現象告知團隊。' },
  '개인정보 처리방침': { ja: 'プライバシーポリシー', zhHans: '隐私政策', zhHant: '隱私政策' },
