  '부산 가볼래?': { ja: '釜山、行ってみる?', zhHans: '要去釜山看看吗?', zhHant: '要去釜山看看嗎?' },
  '시작할 언어 선택': { ja: '開始する言語を選択', zhHans: '选择开始使用的语言', zhHant: '選擇開始使用的語言' },
  '로그인 없이 여행 조건 입력을 시작합니다.': { ja: 'ログインせずに旅行条件の入力を始めます。', zhHans: '无需登录即可开始输入旅行条件。', zhHant: '無需登入即可開始輸入旅行條件。' },
  '피드 둘러보기 →': { ja: 'フィードを見て回る →', zhHans: '浏览动态 →', zhHant: '瀏覽動態 →' },
