  '계정에서 사진을 떼지 못했어요. 잠시 후 다시 시도해 주세요.': { ja: 'アカウントから写真を削除できませんでした。しばらくしてから再度お試しください。', zhHans: '无法从账户中移除照片,请稍后再试。', zhHant: '無法從帳戶中移除照片,請稍後再試。' },
  '기본 프로필로 돌아왔어요.': { ja: 'デフォルトプロフィールに戻りました。', zhHans: '已恢复默认头像。', zhHant: '已恢復預設頭像。' },
