  '프로필을 저장했어요.': { ja: 'プロフィールを保存しました。', zhHans: '个人资料已保存。', zhHant: '個人資料已保存。' },
  '프로필을 저장하지 못했어요.': { ja: 'プロフィールを保存できませんでした。', zhHans: '无法保存个人资料。', zhHant: '無法保存個人資料。' },
  '입력한 값이 달라요. 다시 입력해 주세요.': { ja: '入力した内容が一致しません。もう一度入力してください。', zhHans: '您输入的内容不匹配,请重新输入。', zhHant: '您輸入的內容不符,請重新輸入。' },
