  'AI 여행': { ja: 'AI旅行', zhHans: 'AI 旅行', zhHant: 'AI 旅行' },
  '조건만 알려주면\n일정을 만들어요': { ja: '条件を伝えるだけで\n日程を作ります', zhHans: '只需告诉我们条件\n即可生成行程', zhHant: '只需告訴我們條件\n即可生成行程' },
  '날짜와 취향, 이동 조건을 반영해 나만의 부산 여행을 구성해요.': { ja: '日付・好み・移動条件を反映して自分だけの釜山旅行を組みます。', zhHans: '根据日期、偏好和出行条件,规划专属于您的釜山之旅。', zhHant: '根據日期、偏好和出行條件,規劃專屬於您的釜山之旅。' },
  '장소를 찾고 저장해\n내 여행으로 이어가요': { ja: '場所を探して保存し\n自分の旅行に繋げます', zhHans: '搜索并保存地点\n加入您的旅行', zhHant: '搜尋並保存地點\n加入您的旅行' },
  '이름으로 장소를 찾고, 마음에 든 곳은 부슐랭과 꼭 갈 장소에 담을 수 있어요.': { ja: '名前で場所を探し、気に入った場所はマイプレイスや必ず行く場所に入れられます。', zhHans: '按名称搜索地点,喜欢的可以加入我的地点或必去清单。', zhHant: '按名稱搜尋地點,喜歡的可以加入我的地點或必去清單。' },
  '여행지에서 필요한 말을\n바로 보여주고 들려줘요': { ja: '旅先で必要な言葉を\nすぐに見せて聞かせます', zhHans: '立即展示并朗读\n旅途中需要的话语', zhHant: '立即展示並朗讀\n旅途中需要的話語' },
  '식당과 택시에서 쓸 문장을 크게 보여주거나 한국어 음성으로 들려줘요.': { ja: 'レストランやタクシーで使う文を大きく表示したり韓国語音声で聞かせたりします。', zhHans: '放大显示或用韩语朗读在餐厅和出租车使用的句子。', zhHant: '放大顯示或用韓語朗讀在餐廳和計程車使用的句子。' },
  '해운대와 광안리 2명 맛집 일정 짜줘': { ja: '海雲台と広安里で2人分のグルメ日程を組んで', zhHans: '请为2人规划海云台和广安里的美食行程', zhHant: '請為2人規劃海雲台和廣安里的美食行程' },
  '사진 부탁할 때 한국어 문장 알려줘': { ja: '写真をお願いする時の韓国語の文を教えて', zhHans: '告诉我请人拍照时用的韩语句子', zhHant: '告訴我請人拍照時用的韓語句子' },
  '부산 로컬 스팟 보여줘': { ja: '釜山のローカルスポットを見せて', zhHans: '给我看看釜山的本地景点', zhHant: '給我看看釜山的在地景點' },
  '일정 만들기': { ja: '日程を作成', zhHans: '规划行程', zhHant: '規劃行程' },
  '대화 조건 적용': { ja: '会話の条件を適用', zhHans: '应用对话条件', zhHant: '套用對話條件' },
  '현장 말하기·날씨 준비물': { ja: '現地会話・天気持ち物', zhHans: '现场对话与天气行李', zhHant: '現場對話與天氣行李' },
  '저장한 일정 열기': { ja: '保存した日程を開く', zhHans: '打开已保存的行程', zhHant: '打開已保存的行程' },
  '축제·전통시장 등 다양한 카테고리': { ja: '祭り・伝統市場など多様なカテゴリー', zhHans: '节庆、传统市场等多种类别', zhHant: '節慶、傳統市場等多種類別' },
  '여행이 끝난 뒤': { ja: '旅行が終わった後', zhHans: '旅行结束后', zhHant: '旅行結束後' },
  '지금 바로': { ja: '今すぐ', zhHans: '立即', zhHant: '立即' },
  '가볼래는 어떤 앱인가요?': { ja: 'GABOLLEはどんなアプリですか?', zhHans: 'GABOLLE 是什么样的应用?', zhHant: 'GABOLLE 是什麼樣的應用程式?' },
  '취향·예산·이동 조건을 반영해 부산 일정을 만들고, 장소 저장과 현장 말하기까지 이어주는 여행 앱이에요.': { ja: '好み・予算・移動条件を反映して釜山日程を作成し、場所保存や現地会話まで繋げる旅行アプリです。', zhHans: '一款根据偏好、预算和出行条件生成釜山行程,并支持保存地点和现场对话的旅行应用。', zhHant: '一款根據偏好、預算和出行條件生成釜山行程,並支援保存地點和現場對話的旅行應用程式。' },
  '일정이 바로 만들어지지 않아요.': { ja: '日程がすぐに作成されません。', zhHans: '行程没有立即生成。', zhHant: '行程沒有立即生成。' },
  '내 여행에서 준비 상태를 확인해 주세요. 실패로 표시되면 다시 만들기를 누르고, 같은 문제가 반복되면 화면의 요청 ID와 함께 문의해 주세요.': { ja: 'マイ旅行で準備状況をご確認ください。失敗と表示されたら再作成を押し、同じ問題が繰り返されたら画面のリクエストIDと共にお問い合わせください。', zhHans: '请在我的旅行中查看准备状态。若显示失败,请点击重新生成;若问题反复出现,请附上页面上的请求ID联系我们。', zhHant: '請在我的旅行中查看準備狀態。若顯示失敗,請點擊重新生成;若問題反覆出現,請附上頁面上的請求ID聯絡我們。' },
  '위치 권한을 거부해도 되나요?': { ja: '位置情報の権限を拒否しても大丈夫ですか?', zhHans: '可以拒绝位置权限吗?', zhHant: '可以拒絕位置權限嗎?' },
  '네. 출발지나 장소를 직접 검색할 수 있어요. 위치 권한은 주변 장소와 방문 확인을 더 편하게 쓸 때만 필요해요.': { ja: 'はい。出発地や場所を直接検索できます。位置情報権限は周辺の場所や訪問確認をより便利に使う時だけ必要です。', zhHans: '可以。您可以手动搜索出发地或地点。位置权限仅在需要更方便地使用附近地点和到访确认时才需要。', zhHant: '可以。您可以手動搜尋出發地或地點。位置權限僅在需要更方便地使用附近地點和到訪確認時才需要。' },
  '내 정보는 어떻게 삭제하나요?': { ja: '自分の情報はどのように削除しますか?', zhHans: '如何删除我的信息?', zhHant: '如何刪除我的資訊?' },
  '마이페이지 → 프로필 → 회원 탈퇴에서 삭제되는 항목을 확인한 뒤 계정을 영구 삭제할 수 있어요.': { ja: 'マイページ → プロフィール → 退会で削除される項目を確認した後、アカウントを完全に削除できます。', zhHans: '在个人主页 → 个人资料 → 注销账户中确认将被删除的项目后,即可永久删除账户。', zhHant: '在個人主頁 → 個人資料 → 註銷帳戶中確認將被刪除的項目後,即可永久刪除帳戶。' },
  '공공데이터 출처': { ja: '公共データの出典', zhHans: '公共数据来源', zhHant: '公共數據來源' },
  '가볼래가 활용하는 공공데이터와 그 이용 조건입니다.': { ja: 'GABOLLEが活用する公共データとその利用条件です。', zhHans: 'GABOLLE 所使用的公共数据及其使用条件。', zhHant: 'GABOLLE 所使用的公共數據及其使用條件。' },
  '실제로 처리하는 정보와 그 목적을 투명하게 안내합니다.': { ja: '実際に処理する情報とその目的を透明に案内します。', zhHans: '透明说明我们实际处理的信息及其用途。', zhHant: '透明說明我們實際處理的資訊及其用途。' },
  '가볼래 서비스를 안전하고 편리하게 이용하기 위한 기본 원칙입니다.': { ja: 'GABOLLEサービスを安全かつ便利に利用するための基本原則です。', zhHans: '安全便利地使用 GABOLLE 服务的基本原则。', zhHant: '安全便利地使用 GABOLLE 服務的基本原則。' },
