  '뺀 자리를 채울 다른 장소를 찾지 못해 비워 뒀어요.': { ja: '抜けた場所を埋める別の場所が見つからず空けておきました。', zhHans: '未能找到其他地点填补空缺,因此保留为空。', zhHant: '未能找到其他地點填補空缺,因此保留為空。' },
  '다시 계산하면서 고정된 장소의 시각도 함께 조정됐어요.': { ja: '再計算する際、固定された場所の時刻も一緒に調整されました。', zhHans: '重新计算时,已锁定地点的时间也一并调整。', zhHant: '重新計算時,已鎖定地點的時間也一併調整。' },
