  '지금 날씨에 어울려요': { ja: '今の天気に合っています', zhHans: '适合现在的天气', zhHant: '適合現在的天氣' },
  '근처에서 인기 있어요': { ja: '近くで人気があります', zhHans: '在附近很受欢迎', zhHant: '在附近很受歡迎' },
  '추천 조건 반영': { ja: 'おすすめ条件を反映', zhHans: '反映推荐条件', zhHant: '反映推薦條件' },
  '지금 갈 곳 추천은 아직 서버와 연결되지 않았어요 — 예시 후보를 보여드려요.': { ja: '今行ける場所のおすすめはまだサーバーと接続されていません — 例の候補をお見せします。', zhHans: '"现在可去"推荐功能尚未连接服务器——为您展示示例候选。', zhHant: '「現在可去」推薦功能尚未連接伺服器——為您展示範例候選。' },
  '남은 시간 안에 갈 만한 곳을 찾지 못했어요. 시간을 늘려 다시 찾아보세요.': { ja: '残り時間内に行ける場所が見つかりませんでした。時間を増やして再度探してみてください。', zhHans: '未能在剩余时间内找到合适的去处,请延长时间后重试。', zhHant: '未能在剩餘時間內找到合適的去處,請延長時間後重試。' },
  '지금 조건에 맞는 곳을 찾았어요.': { ja: '今の条件に合う場所を見つけました。', zhHans: '找到了符合当前条件的地方。', zhHant: '找到了符合目前條件的地方。' },
  '날씨 정보 없이 계산했어요.': { ja: '天気情報なしで計算しました。', zhHans: '未使用天气信息进行了计算。', zhHant: '未使用天氣資訊進行了計算。' },
  '지금 갈 곳을 찾지 못했어요.': { ja: '今行ける場所が見つかりませんでした。', zhHans: '目前未能找到可去的地方。', zhHant: '目前未能找到可去的地方。' },
  '기본': { ja: '基本', zhHans: '基本', zhHant: '基本' },
  '취향': { ja: '好み', zhHans: '偏好', zhHant: '偏好' },
  '제약': { ja: '制約', zhHans: '限制', zhHant: '限制' },
  '조건에 맞는 장소를 찾지 못했어요. 날짜·예산·취향 조건을 조금 넓혀서 다시 시도해 주세요.': { ja: '条件に合う場所が見つかりませんでした。日付・予算・好み条件を少し広げて再度お試しください。', zhHans: '未能找到符合条件的地点,请放宽日期、预算或偏好条件后重试。', zhHant: '未能找到符合條件的地點,請放寬日期、預算或偏好條件後重試。' },
  '조건을 모두 만족하는 일정을 만들지 못했어요. 조건을 조정해서 다시 시도해 주세요.': { ja: '条件をすべて満たす日程を作成できませんでした。条件を調整して再度お試しください。', zhHans: '未能生成满足所有条件的行程,请调整条件后重试。', zhHant: '未能生成滿足所有條件的行程,請調整條件後重試。' },
  '출발지 정보가 없어요. 여행 조건에서 출발지를 다시 확인해 주세요.': { ja: '出発地情報がありません。旅行条件で出発地を再度確認してください。', zhHans: '缺少出发地信息,请在旅行条件中重新确认出发地。', zhHant: '缺少出發地資訊,請在旅行條件中重新確認出發地。' },
  '추천 엔진에 일시적인 문제가 있어요. 잠시 후 다시 시도해 주세요.': { ja: 'おすすめエンジンに一時的な問題があります。しばらくしてから再度お試しください。', zhHans: '推荐引擎暂时出现问题,请稍后再试。', zhHant: '推薦引擎暫時出現問題,請稍後再試。' },
  '다른 곳에서 먼저 일정이 바뀌었어요. 새로고침 후 다시 시도해 주세요.': { ja: '他の場所で先に日程が変更されました。更新後再度お試しください。', zhHans: '行程已被其他地方先行更改,请刷新后重试。', zhHant: '行程已被其他地方先行更改,請重新整理後重試。' },
  '일정을 만드는 중 문제가 생겼어요. 잠시 후 다시 시도해 주세요.': { ja: '日程作成中に問題が発生しました。しばらくしてから再度お試しください。', zhHans: '生成行程时出现问题,请稍后再试。', zhHant: '生成行程時出現問題,請稍後再試。' },
