  '조건에 맞는 코스를 찾았어요.': { ja: '条件に合うコースを見つけました。', zhHans: '找到了符合条件的路线。', zhHant: '找到了符合條件的路線。' },
  '아직 생성된 추천이 없어요. 여행 조건을 확인하고 생성을 시작해 주세요.': { ja: 'まだ生成されたおすすめがありません。旅行条件を確認して生成を開始してください。', zhHans: '尚未生成推荐,请确认旅行条件后开始生成。', zhHant: '尚未生成推薦,請確認旅行條件後開始生成。' },
  '보통 대표 명소와 현지인 공간 중 어느 쪽에 더 끌리세요?': { ja: '普段代表的な名所と地元の空間、どちらに惹かれますか?', zhHans: '您平时更倾向于知名景点还是当地人常去的地方?', zhHant: '您平時更傾向於知名景點還是當地人常去的地方?' },
