  '부산에서 보통 어떤 음식을 찾으세요? 여러 개 골라도 돼요.': { ja: '釜山で普段どんな食べ物を探しますか?複数選んでも構いません。', zhHans: '您在釜山平时通常找什么样的美食?可以多选。', zhHant: '您在釜山平時通常找什麼樣的美食?可以多選。' },
