  '예, 경사는 피하고 싶어요': { ja: 'はい、坂道は避けたいです', zhHans: '是的,我想避开坡道', zhHant: '是的,我想避開坡道' },
  '일정과 동선에서 가파른 길을 빼요': { ja: '日程と動線から急な道を除きます', zhHans: '我们会在行程和路线中排除陡峭的路段', zhHant: '我們會在行程和路線中排除陡峭的路段' },
